import{_ as t,o,c as s,ag as a}from"./chunks/framework.BaNuf0sO.js";const p=JSON.parse('{"title":"menu 菜单族","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/menu/README.md","filePath":"docs/core/src/components/menu/README.md"}'),n={name:"docs/core/src/components/menu/README.md"};function i(d,e,r,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="menu-菜单族" tabindex="-1">menu 菜单族 <a class="header-anchor" href="#menu-菜单族" aria-label="Permalink to &quot;menu 菜单族&quot;">​</a></h1><p>配置化菜单族：<code>MenuTree</code>（基于 ElMenu 的菜单，含<strong>树形 / 分组</strong>双渲染形态）+ <code>MenuItemSub</code>（递归子菜单分组件，MenuTree 内部递归用）。</p><h2 id="两种渲染形态-menutree-的-groupmode" tabindex="-1">两种渲染形态（<code>MenuTree</code> 的 <code>groupMode</code>） <a class="header-anchor" href="#两种渲染形态-menutree-的-groupmode" aria-label="Permalink to &quot;两种渲染形态（`MenuTree` 的 `groupMode`）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th><code>groupMode</code></th><th>父级节点渲染成</th><th>交互</th><th>适用</th></tr></thead><tbody><tr><td><strong>树形</strong>（默认）</td><td><code>false</code></td><td><code>ElSubMenu</code>（手风琴）</td><td>点击展开 / 收起，默认收起</td><td>菜单量大 / 层级深，靠折叠控制列表长度</td></tr><tr><td><strong>分组</strong></td><td><code>true</code></td><td><code>ElMenuItemGroup</code>（分组标题：小字号 + 弱色，<strong>不可点、不可折叠、不导航</strong>）</td><td>无——子项常驻全展开</td><td>菜单量小（经验值 ≤ 25 叶子）/ 层级浅，要求零点击看见全部导航</td></tr></tbody></table><p>分组形态即业界通称的 <strong>grouped / sectioned navigation</strong>（父级叫 section heading / group label）：shadcn/ui <code>SidebarGroupLabel</code>、Ant Design <code>Menu type:&quot;group&quot;</code>、Element Plus <code>el-menu-item-group</code>、Material 3 / Fluent 2 的 navigation section header 都是同一范式；Linear / Stripe / Vercel / Supabase / GitHub Settings 等产品的侧栏走的都是它而非手风琴。</p><p>本族<strong>不自造分组组件</strong>——EP 的 <code>el-menu-item-group__title</code> 原生就是 <code>font-size: 12px</code> + <code>--el-text-color-secondary</code>，正是「字号偏小、颜色偏弱」，直接复用。</p><blockquote><p>⚠️ 分组形态<strong>只吃掉一层</strong>父级：三级及以上菜单中 L1 → 分组标题，L2 若仍有 <code>children</code> → 继续走 <code>ElSubMenu</code> 手风琴（混合渲染）。详见 <a href="/done-coding-showcase/docs/core/src/components/menu/docs/README-MenuTree.html">README-MenuTree.md</a>。</p></blockquote><h2 id="组件文档-docs" tabindex="-1">组件文档（docs/） <a class="header-anchor" href="#组件文档-docs" aria-label="Permalink to &quot;组件文档（docs/）&quot;">​</a></h2><ul><li><a href="/done-coding-showcase/docs/core/src/components/menu/docs/README-MenuTree.html">MenuTree</a> — 菜单主体（menus 递归 + <code>groupMode</code> 树形 / 分组双形态 + routerMode / autoClose / collapse + open/close expose）</li><li><a href="/done-coding-showcase/docs/core/src/components/menu/docs/README-MenuItemSub.html">MenuItemSub</a> — 递归子菜单分组件（ElSubMenu 递归节点，一般由 MenuTree 自用；分组形态下承接 L2 及更深层级）</li></ul><h2 id="菜单项徽标" tabindex="-1">菜单项徽标 <a class="header-anchor" href="#菜单项徽标" aria-label="Permalink to &quot;菜单项徽标&quot;">​</a></h2><p>两种形态下，凡渲染出路由 <code>path</code> 的位置（叶子项 / ElSubMenu 标题 / 分组标题）都会按 <strong><code>path</code> 作 key</strong> 查 <code>bridge.badge</code> 注册表，命中则渲染绝对定位角标（数量 / 新 / 更新 / 内测 / 开发中 / 自定义），<strong>不压字、不改变宿主尺寸</strong>；未命中零影响。</p><p>无需在菜单数据里另配 key。完整契约见 <a href="/done-coding-showcase/docs/core/src/bridge/docs/README.html">bridge 文档 · 徽标注册表</a>。</p><blockquote><p>core <strong>不做</strong>子级到父级的冒泡聚合——需要「模块上有引导点」由 app 自己算完往父级 path 写 entry，理由见上述文档。</p></blockquote><h2 id="新标签页打开-meta-menu-target" tabindex="-1">新标签页打开（<code>meta.menu.target</code>） <a class="header-anchor" href="#新标签页打开-meta-menu-target" aria-label="Permalink to &quot;新标签页打开（`meta.menu.target`）&quot;">​</a></h2><p>路由 <code>meta.menu.target: &quot;_blank&quot;</code>（缺省 <code>&quot;_self&quot;</code>）⇒ 点该菜单项（侧栏叶子项 / 顶栏模块条）<strong>新标签页打开本路由</strong>， 当前页路由与激活高亮<strong>不变</strong>。适用于独立展示页 / 文档页 / 外部系统入口这类「不该把用户带离后台」的一级入口。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/open-platform&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">meta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;开放平台&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">menu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;_blank&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } } }</span></span></code></pre></div><ul><li>href 经 <code>router.resolve(path).href</code> 解析（含 base / hash 前缀），<code>window.open(href, &quot;_blank&quot;, &quot;noopener&quot;)</code>。</li><li>只作用于<strong>菜单点击</strong>；地址栏直达、分享链接等其它导航照常。</li><li>实现：叶子项统一由内部件 <code>MenuItemLeaf</code> 渲染，<code>_blank</code> 项不给 <code>ElMenuItem</code> index —— EP 对 nil index 直接返回（不 push、不改激活项）， 点击由 <code>MenuItemLeaf</code> 自己开新标签页。[MUST NOT] 改成「保留 index 在 <code>select</code> 里拦」：router 模式下 EP 先 push 后 emit，拦不住。</li><li>只支持叶子项（有子项的父级本就不导航）；外链 <code>href</code> 不在本字段范围。</li></ul><h2 id="关键类型" tabindex="-1">关键类型 <a class="header-anchor" href="#关键类型" aria-label="Permalink to &quot;关键类型&quot;">​</a></h2><ul><li><code>RouteMetaResolveRaw</code>（@/types，menus / menuFlatList 数据契约）</li><li>内部不导出：<code>MenuItemLeaf</code>（叶子项，MenuTree / MenuItemSub 共用）</li></ul><h2 id="范式页-apps-reference" tabindex="-1">范式页（apps/reference） <a class="header-anchor" href="#范式页-apps-reference" aria-label="Permalink to &quot;范式页（apps/reference）&quot;">​</a></h2><ul><li>真实消费方：<code>AppSidebar</code>（packages/core/src/components/app-layout/AppSidebar.vue）——生产级驱动点；其 <code>groupMode</code> 由 <code>bridge.APP_LAYOUT_SIDEBAR_CONFIG.menuGroupMode</code> 驱动，业务侧不直传</li><li>菜单数据契约范式：<code>apps/reference/src/router/modules/test.ts</code>（meta.menu 的 show / icon / sort / target 驱动渲染、排序与点击打开方式）</li><li>注意：<code>/menu/showcase/Page1/2/3</code> 是菜单渲染出的叶子路由页，不是 MenuTree 的用法示范</li></ul>',21)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
